CREATE TABLE IF NOT EXISTS "madoc"."presidents" (
    "number" INTEGER GENERATED BY DEFAULT AS IDENTITY (START WITH 1) PRIMARY KEY CHECK ("number" >= 1),
    "name" VARCHAR(100) NOT NULL,
    "start_year" INTEGER NOT NULL,
    "end_year" INTEGER,
    "photo_id" VARCHAR(255)
);

ON CONFLICT ("number") DO NOTHING;

SELECT setval(
    pg_get_serial_sequence('"madoc"."presidents"', 'number'),
    COALESCE((SELECT MAX("number") FROM "madoc"."presidents"), 1)
);
